-- Salario: production schema. All rows are scoped by household membership.
create extension if not exists pg_trgm;
create type public.list_kind as enum ('shopping','transport','other','savings','custom');
create type public.list_mode as enum ('permanent','by_period');
create type public.section_status as enum ('planned','active','closed');
create table if not exists public.profiles (id uuid primary key, telegram_id bigint unique not null, first_name text not null, last_name text, username text, photo_url text, language_code text, timezone text not null default 'UTC', created_at timestamptz not null default now());
create table if not exists public.households (id uuid primary key default gen_random_uuid(), name text not null, created_by uuid not null references public.profiles(id), currency text not null default 'RUB', settings jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.household_members (household_id uuid references public.households(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, role text not null default 'member', joined_at timestamptz not null default now(), primary key(household_id,user_id));
create table if not exists public.household_invites (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, code text unique not null, created_by uuid not null references public.profiles(id), expires_at timestamptz not null, used_by uuid references public.profiles(id), used_at timestamptz);
create table if not exists public.categories (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, name text not null, icon text, color text, kind text not null default 'custom');
create table if not exists public.lists (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, title text not null, icon text, color text, kind public.list_kind not null default 'custom', mode public.list_mode not null default 'permanent', sort_order int not null default 0, archived_at timestamptz, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table if not exists public.list_sections (id uuid primary key default gen_random_uuid(), list_id uuid not null references public.lists(id) on delete cascade, household_id uuid not null references public.households(id) on delete cascade, title text not null, period_start date not null, period_end date not null, planned_for date not null, status public.section_status not null default 'planned', closed_at timestamptz);
create table if not exists public.catalog_items (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, name text not null, normalized_name text not null, category_id uuid references public.categories(id), default_unit text, default_qty numeric not null default 1, last_price numeric, avg_price numeric, times_added int not null default 0, times_bought int not null default 0, last_added_at timestamptz, last_bought_at timestamptz, is_hidden boolean not null default false, unique(household_id,normalized_name));
create table if not exists public.list_items (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, list_id uuid not null references public.lists(id) on delete cascade, section_id uuid references public.list_sections(id) on delete cascade, catalog_item_id uuid references public.catalog_items(id), title text not null, note text, quantity numeric not null default 1, unit text, price numeric, price_is_total boolean not null default false, category_id uuid references public.categories(id), is_done boolean not null default false, done_at timestamptz, done_by uuid references public.profiles(id), due_date date, sort_order int not null default 0, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.list_totals (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, list_id uuid not null references public.lists(id) on delete cascade, section_id uuid references public.list_sections(id), amount numeric not null, comment text, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table if not exists public.recurring_rules (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, list_id uuid not null references public.lists(id) on delete cascade, title text not null, amount numeric, category_id uuid references public.categories(id), frequency text not null, day_of_month int, interval_days int, next_run_on date, is_active boolean not null default true);
create table if not exists public.savings_goals (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, title text not null, target_amount numeric not null, icon text, color text, deadline date, archived_at timestamptz);
create table if not exists public.savings_contributions (id uuid primary key default gen_random_uuid(), goal_id uuid not null references public.savings_goals(id) on delete cascade, household_id uuid not null references public.households(id) on delete cascade, amount numeric not null, note text, contributed_at timestamptz not null default now(), user_id uuid not null references public.profiles(id));
create table if not exists public.budgets (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, category_id uuid references public.categories(id), period_amount numeric not null, created_at timestamptz not null default now());
create table if not exists public.non_working_days (id uuid primary key default gen_random_uuid(), household_id uuid references public.households(id) on delete cascade, date date not null, title text not null);
create or replace function public.is_household_member(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from household_members where household_id=target and user_id=auth.uid()) $$;
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create trigger list_items_touch before update on public.list_items for each row execute function public.touch_updated_at();
create or replace function public.normalize_catalog_item() returns trigger language plpgsql as $$ begin new.normalized_name=lower(regexp_replace(trim(new.name),'\\s+',' ','g')); return new; end $$;
create trigger catalog_normalize before insert or update on public.catalog_items for each row execute function public.normalize_catalog_item();
create index if not exists lists_household_idx on public.lists(household_id,created_at); create index if not exists items_section_done_idx on public.list_items(section_id,is_done); create index if not exists catalog_search_idx on public.catalog_items using gin(normalized_name gin_trgm_ops);
alter table public.profiles enable row level security; alter table public.households enable row level security; alter table public.household_members enable row level security; alter table public.lists enable row level security; alter table public.list_sections enable row level security; alter table public.catalog_items enable row level security; alter table public.list_items enable row level security; alter table public.list_totals enable row level security; alter table public.categories enable row level security; alter table public.recurring_rules enable row level security; alter table public.savings_goals enable row level security; alter table public.savings_contributions enable row level security; alter table public.budgets enable row level security; alter table public.non_working_days enable row level security;
create policy profiles_self on public.profiles for select using (id=auth.uid());
create policy households_member on public.households for all using (is_household_member(id)) with check (created_by=auth.uid());
do $$ declare t text; begin foreach t in array array['household_members','lists','list_sections','catalog_items','list_items','list_totals','categories','recurring_rules','savings_goals','savings_contributions','budgets','non_working_days'] loop execute format('create policy %I_member on public.%I for all using (is_household_member(household_id)) with check (is_household_member(household_id))',t,t); end loop; end $$;
